class Solution {
public:
    int maxSumRangeQuery(vector<int>& nums, vector<vector<int>>& requests) {
        const int MOD = 1000000007;
        const int MAXV = 100001;
        int n = nums.size();
        vector<long long> freq(n, 0);
        for (auto& r : requests) {
            freq[r[0]]++;
            if (r[1] + 1 < n) freq[r[1] + 1]--;
        }
        for (int i = 1; i < n; i++) freq[i] += freq[i - 1];

        vector<int> cntN(MAXV, 0), cntF(MAXV, 0);
        for (int x : nums) cntN[x]++;
        for (int i = 0; i < n; i++) {
            int f = (int)freq[i];
            if (f >= 0 && f < MAXV) cntF[f]++;
        }

        long long ans = 0;
        int i = MAXV - 1, j = MAXV - 1;
        while (i >= 0 && j >= 0) {
            while (i >= 0 && cntN[i] == 0) i--;
            while (j >= 0 && cntF[j] == 0) j--;
            if (i < 0 || j < 0) break;
            long long pairs = min(cntN[i], cntF[j]);
            ans = (ans + pairs * ((long long)i * j % MOD)) % MOD;
            cntN[i] -= (int)pairs;
            cntF[j] -= (int)pairs;
        }
        return (int)ans;
    }
};
